#!/usr/bin/env node
/**
 * CHILD side of the verifyHeavyLock exercise.
 *
 * Runs as a REAL Node process that has (or deliberately has NOT) inherited an
 * exclusive flock descriptor from its parent shell, and calls the ACTUAL
 * exported verifyHeavyLock from finale-window-probe.mjs. This is not a test of
 * buildStdio and not a copied re-implementation.
 *
 * argv: --fd <n> --lock <path> [--contend] [--label <s>]
 */
import { readlinkSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { verifyHeavyLock } from '/home/thomasphillip/Projects/vox/.codex/production-runs/2026-09-05-after-the-hearth/verifier/probes/finale-window/finale-window-probe.mjs';

const arg = (n, d = null) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : d; };
const fdRaw = arg('fd');
const fd = fdRaw === 'null' ? null : Number(fdRaw);
const lockPath = arg('lock') === 'null' ? null : arg('lock');
const contend = process.argv.includes('--contend');

// The exact causal contrast, in the SAME process that owns the descriptor.
// (The fd transport itself is already proven by
//  logs/finale-window-runtime/fd-transport-diagnostic.mjs; this only records
//  which reader observes the inherited descriptor.)
const readers = {};
try { readers.inProcessReadlinkSync = readlinkSync(`/proc/self/fd/${fd}`); }
catch (e) { readers.inProcessReadlinkSync = `ERR:${e.code ?? e.message}`; }
try { readers.spawnedReadlinkOldWay = execFileSync('readlink', ['-f', `/proc/self/fd/${fd}`], { encoding: 'utf8' }).trim(); }
catch (e) { readers.spawnedReadlinkOldWay = `ERR:${e.code ?? String(e.message).slice(0, 60)}`; }

const result = verifyHeavyLock({ lockPath, fd, probeContention: contend });

process.stdout.write(JSON.stringify({
  label: arg('label', 'unlabelled'), pid: process.pid, fd, lockPath, contend, readers, result
}) + '\n');

