#!/usr/bin/env node
/**
 * PARENT side: exercises the ACTUAL exported verifyHeavyLock in real Node
 * children against a UNIQUE temporary lock file (never the production heavy
 * lock, so no shared-lock contention is created for anyone else).
 *
 * Cases
 *   A held-exclusive-fd9      shell exec 9>lock + flock -x 9, child inherits -> MUST pass, contention exit 1
 *   B missing-fd              held shell, but verify a descriptor that is NOT open -> MUST refuse
 *   C wrong-fd-target         fd open on a DIFFERENT file -> MUST refuse (path + dev/inode)
 *   D unheld-fd9              fd 9 open on the lock but NEVER flocked -> MUST refuse (no kernel lock, 2nd flock wins)
 *   E no-lock-path / no-fd    argument guards -> MUST refuse
 */
import { execFileSync, spawnSync } from 'node:child_process';
import { writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { createHash, randomBytes } from 'node:crypto';

const HERE = '/home/thomasphillip/Projects/vox/.codex/production-runs/2026-09-05-after-the-hearth/logs/finale-window-fd-runtime';
const CHILD = `${HERE}/fd-check.mjs`;
const uniq = `${process.pid}-${randomBytes(4).toString('hex')}`;
const LOCK = `/tmp/finale-window-fdcheck-${uniq}.lock`;
const OTHER = `/tmp/finale-window-fdcheck-${uniq}.other`;
writeFileSync(LOCK, ''); writeFileSync(OTHER, '');

const NODE = process.execPath;
const run = (script) => {
  const r = spawnSync('bash', ['-c', script], { encoding: 'utf8', timeout: 60000 });
  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
};
const parse = (out) => { try { return JSON.parse(String(out).trim().split('\n').filter(Boolean).pop()); } catch { return null; } };

const cases = [];
const add = (name, expectation, raw, judge) => {
  const rec = parse(raw.stdout);
  let pass = false, why = 'no child JSON';
  if (rec) { const v = judge(rec); pass = v.pass; why = v.why; }
  cases.push({ name, expectation, pass, why, shellStatus: raw.status,
               stderr: String(raw.stderr).slice(0, 400), child: rec });
};

// A: genuinely held, inherited exclusive fd 9, contention probe on.
add('A-held-exclusive-inherited-fd9', 'owned=true; in-process readlink resolves; contention exit 1',
  run(`exec 9>${LOCK}; flock -n -x 9 || exit 75; ${NODE} ${CHILD} --fd 9 --lock ${LOCK} --contend --label A-held`),
  (r) => ({
    pass: r.result.owned === true
       && r.result.problems.length === 0
       && r.result.fdTarget === LOCK
       && r.result.fdIdentity?.match === true
       && Array.isArray(r.result.procLock) && r.result.procLock.length > 0
       && r.result.contentionProbe?.conclusive === true
       && r.result.contentionProbe?.status === 1
       && r.result.contentionProbe?.acquiredBySecondProcess === false,
    why: `owned=${r.result.owned} problems=${JSON.stringify(r.result.problems)} contention=${JSON.stringify(r.result.contentionProbe)}`
  }));

// B: same held shell, but ask about a descriptor that is not open.
add('B-missing-fd-refused', 'owned=false; "not open in this process"',
  run(`exec 9>${LOCK}; flock -n -x 9 || exit 75; ${NODE} ${CHILD} --fd 8 --lock ${LOCK} --contend --label B-missing`),
  (r) => ({ pass: r.result.owned === false && r.result.problems.some((p) => /not open in this process/.test(p)),
            why: JSON.stringify(r.result.problems) }));

// C: descriptor open, but on the WRONG file.
add('C-wrong-fd-target-refused', 'owned=false; target and dev/inode mismatch reported',
  run(`exec 9>${LOCK}; flock -n -x 9 || exit 75; exec 8>${OTHER}; ${NODE} ${CHILD} --fd 8 --lock ${LOCK} --label C-wrong`),
  (r) => ({ pass: r.result.owned === false && r.result.problems.some((p) => /points at/.test(p)),
            why: JSON.stringify(r.result.problems) }));

// D: fd 9 open on the lock but NEVER flocked -> not exclusive, second flock wins.
add('D-unheld-fd9-refused', 'owned=false; no kernel lock; second flock succeeds => CONTENTION PROOF FAILED',
  run(`exec 9>${LOCK}; ${NODE} ${CHILD} --fd 9 --lock ${LOCK} --contend --label D-unheld`),
  (r) => ({ pass: r.result.owned === false
              && r.result.problems.some((p) => /no kernel lock recorded/.test(p))
              && r.result.contentionProbe?.status === 0
              && r.result.contentionProbe?.acquiredBySecondProcess === true
              && r.result.problems.some((p) => /CONTENTION PROOF FAILED/.test(p)),
            why: `problems=${JSON.stringify(r.result.problems)} contention=${JSON.stringify(r.result.contentionProbe)}` }));

// E1/E2: argument guards.
add('E1-no-fd-refused', 'owned=false; inherited-fd required',
  run(`exec 9>${LOCK}; flock -n -x 9 || exit 75; ${NODE} ${CHILD} --fd null --lock ${LOCK} --label E1`),
  (r) => ({ pass: r.result.owned === false && r.result.problems.some((p) => /heavy-lock-fd/.test(p)), why: JSON.stringify(r.result.problems) }));
add('E2-no-lock-path-refused', 'owned=false; lock path required',
  run(`exec 9>${LOCK}; flock -n -x 9 || exit 75; ${NODE} ${CHILD} --fd 9 --lock null --label E2`),
  (r) => ({ pass: r.result.owned === false && r.result.problems.some((p) => /heavy-lock path/.test(p)), why: JSON.stringify(r.result.problems) }));

// The recorded causal contrast from case A (old reader vs new reader).
const A = cases[0].child;
const causal = {
  inProcessReadlinkSync: A?.readers?.inProcessReadlinkSync ?? null,
  spawnedReadlinkOldWay: A?.readers?.spawnedReadlinkOldWay ?? null,
  oldReaderWouldHaveFailed: /^ERR:/.test(String(A?.readers?.spawnedReadlinkOldWay)),
  note: 'Old code read /proc/self/fd/9 inside the SPAWNED readlink, which never inherits fd 9. Transport itself already proven by logs/finale-window-runtime/fd-transport-diagnostic.mjs.'
};

try { execFileSync('rm', ['-f', LOCK, OTHER]); } catch {}

const failed = cases.filter((c) => !c.pass);
const out = {
  schema: 'paravoxia.verifier.finaleWindowFdCheck.v1',
  at: new Date().toISOString(),
  tempLock: LOCK, note: 'unique temporary lock; production heavy lock untouched',
  probeSha256AtRun: createHash('sha256').update(readFileSync('/home/thomasphillip/Projects/vox/.codex/production-runs/2026-09-05-after-the-hearth/verifier/probes/finale-window/finale-window-probe.mjs')).digest('hex'),
  cases: cases.length, failed: failed.length, causal, results: cases
};
mkdirSync(HERE, { recursive: true });
writeFileSync(`${HERE}/fd-check-result.json`, JSON.stringify(out, null, 1));
console.log(JSON.stringify(out, null, 1));
process.exit(failed.length ? 1 : 0);

