  preEdgeMs: Number(arg('pre-edge-ms', String(DEFAULT_WINDOW.preEdgeMs))),
  postEdgeMs: Number(arg('post-edge-ms', String(DEFAULT_WINDOW.postEdgeMs))),
  timerMs: Number(arg('timer-ms', '8')) };
